// cppparse_rt.cpp - version 5 runtime for code generated by cppparse (x86-64, Windows).
//
// Exceptions use setjmp/longjmp. The generated code keeps one frame per try
// region in its stack frame:
//
//     lea rcx, [frame]  ; call cppparse_push_frame
//     lea rcx, [frame]  ; xor edx, edx ; call _setjmp      (frame pointer NULL: no unwinding)
//     test eax, eax     ; jne dispatch
//     ... try body ...
//     lea rcx, [frame]  ; call cppparse_pop_frame           (also before return/break/continue)
//   dispatch:
//     lea rcx, [frame]  ; call cppparse_pop_frame
//     lea rcx, "type"   ; call cppparse_match ; test eax, eax ; jne handler   (per catch clause)
//     call cppparse_rethrow                                   (no clause matched)
//   handler:
//     call cppparse_catch_begin   -> rax = address of the thrown object (a copy owned by the runtime)
//     ... handler body ...
//     call cppparse_catch_end
//
// "throw x" copies the object (its size and a type descriptor "Class;Base1;Base2@16" or the
// scalar type name, "D*;B1*;B2*+16;V*+v0:4;void*" for a pointer to a class (V a virtual base: found
// through the object's vbtable), come from the generated code) and longjmps to the innermost frame. The
// frame stack, the exception in flight and the caught ones are per thread.
//
// With --eh=table the generated code has no frames: a try region is a list of code ranges in the
// function's unwind info, each with its landing pad (the dispatch stub above, without the pop).
// "throw" walks the stack with the Windows unwind tables (dispatch below) and enters the first
// landing pad whose range holds a frame's call site. Both models can be mixed in one program.
//
// Build: cl /c /EHsc cppparse_rt.cpp, then link the object with the cppparse-generated .obj.
// Strict C++98 (C subset).
#ifndef _WIN32
#error "the cppparse runtime serves the 64-bit Windows target only"
#endif
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <intrin.h>
#include <setjmp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

extern "C" {

struct cppparse_frame {
    jmp_buf                buf;        /* filled by _setjmp in the generated code (16-byte aligned) */
    struct cppparse_frame* prev;
    void*                  reserved;
};

struct cppparse_exception {
    void*         object;
    const char*   type;
    unsigned long size;
    void        (*dtor)(void*);   /* destructor of a class object thrown with cppparse_throw_owned, or 0 */
    void**        slot;           /* behind a thrown pointer: the adjusted pointer a handler of a pointer to a base gets */
};

/* per thread: the compiler runs its phases on a worker pool, and every thread has its own chain of frames */
static __declspec(thread) struct cppparse_frame*    g_top = 0;
static __declspec(thread) struct cppparse_exception g_inflight = { 0, 0, 0, 0, 0 };

static void dropException(struct cppparse_exception* e)
{
    if (e->object && e->dtor) e->dtor(e->object);
    free(e->object);
    e->object = 0;
    e->dtor = 0;
    e->slot = 0;
}
/* std::set_terminate / set_unexpected: the handlers the library installs; the defaults abort and (unexpected)
   terminate, as C++98 18.6 says; an unhandled exception and an exception leaving a destructor during unwinding
   call terminate */
static void (*g_terminateHandler)(void) = 0;
static void (*g_unexpectedHandler)(void) = 0;
void cppparse_terminate(void);
/* the exceptions caught and not yet released, innermost last (a handler that calls deeper keeps its own alive):
   a per-thread array that doubles as handlers nest */
static __declspec(thread) struct cppparse_exception* g_caught = 0;
static __declspec(thread) int                        g_caughtCount = 0;
static __declspec(thread) int                        g_caughtCap = 0;

static void pushCaught(const struct cppparse_exception* e)
{
    if (g_caughtCount == g_caughtCap) {
        int cap = g_caughtCap ? g_caughtCap * 2 : 32;
        struct cppparse_exception* grown = (struct cppparse_exception*)realloc(g_caught, (size_t)cap * sizeof(struct cppparse_exception));
        if (!grown) { fprintf(stderr, "cppparse runtime: out of memory for %d nested handlers\n", cap); abort(); }
        g_caught = grown;
        g_caughtCap = cap;
    }
    g_caught[g_caughtCount++] = *e;
}

void cppparse_push_frame(struct cppparse_frame* f)
{
    f->prev = g_top;
    g_top = f;
}

void cppparse_pop_frame(struct cppparse_frame* f)
{
    if (g_top != f) fprintf(stderr, "cppparse runtime: try frame popped out of order\n");
    g_top = f->prev;
}

/* the handler named in the unwind info of a function with table-based try regions (--eh=table). Windows calls it
   only when its own SEH dispatch passes such a frame (an access violation, a cl throw); cppparse's exceptions do not
   go through SEH, so it always lets the search go on. Its range table follows it in the unwind info */
EXCEPTION_DISPOSITION cppparse_eh_handler(struct _EXCEPTION_RECORD* record, void* frame, struct _CONTEXT* context, void* dispatcher)
{
    (void)record; (void)frame; (void)context; (void)dispatcher;
    return ExceptionContinueSearch;
}

#define CPPPARSE_EH_MAGIC 0x58505043UL   /* "CPPX", the first word of the range table */

/* sends the exception in flight to the nearest place that takes it, walking the stack from here with the unwind
   tables: a table landing pad (the range of the frame's call site, --eh=table) is entered with RtlRestoreContext,
   which gives the frame back its callee-saved registers as they were at that call; a setjmp frame (the default
   model) is entered with longjmp once the walk has passed the stack frame that holds it. With neither, the
   exception is unhandled: nothing has been unwound, the program stops */
static void dispatch(void)
{
    CONTEXT ctx;
    int i;
    RtlCaptureContext(&ctx);
    for (i = 0; i < 100000 && ctx.Rip; ++i) {
        DWORD64 base = 0;
        PRUNTIME_FUNCTION rf = RtlLookupFunctionEntry(ctx.Rip, &base, 0);
        if (!rf) { ctx.Rip = *(DWORD64*)ctx.Rsp; ctx.Rsp += 8; }      /* a leaf without a table entry */
        else {
            CONTEXT frame = ctx;                                       /* this function, at its call site */
            void* data = 0;
            DWORD64 establisher = 0;
            PEXCEPTION_ROUTINE handler = RtlVirtualUnwind(UNW_FLAG_EHANDLER, base, ctx.Rip, rf, &ctx, &data, &establisher, 0);
            if (handler && data && ((const unsigned long*)data)[0] == CPPPARSE_EH_MAGIC) {
                const unsigned long* t = (const unsigned long*)data;
                const DWORD64 at = frame.Rip - base - 1;               /* inside the call instruction */
                unsigned long k;
                for (k = 0; k < t[1]; ++k)
                    if (at >= t[2 + 3 * k] && at < t[3 + 3 * k]) {
                        frame.Rip = base + t[4 + 3 * k];
                        RtlRestoreContext(&frame, 0);
                    }
            }
        }
        /* the walk has left the stack frame that holds the innermost setjmp frame */
        if (g_top && (DWORD64)g_top < ctx.Rsp) longjmp(g_top->buf, 1);
    }
    if (!g_terminateHandler) fprintf(stderr, "cppparse runtime: unhandled exception of type %s\n", g_inflight.type ? g_inflight.type : "?");
    cppparse_terminate();   /* the handler std::set_terminate installed, else abort */
}

void cppparse_throw(const void* object, const char* type, unsigned long size)
{
    const unsigned long at = (size + 7) & ~7UL;
    void* copy = malloc(at + sizeof(void*));
    if (object && size) memcpy(copy, object, size);
    g_inflight.object = copy;
    g_inflight.type = type;
    g_inflight.size = size;
    g_inflight.dtor = 0;
    g_inflight.slot = (void**)((char*)copy + at);
    dispatch();
}

/* a class object already copy-constructed into malloc storage by the generated code; the runtime
   owns it and runs dtor (the class destructor, this in rcx) before freeing it */
void cppparse_throw_owned(void* object, const char* type, unsigned long size, void (*dtor)(void*))
{
    g_inflight.object = object;
    g_inflight.type = type;
    g_inflight.size = size;
    g_inflight.dtor = dtor;
    g_inflight.slot = 0;
    dispatch();
}

/* "const Failure &" -> "Failure", "char const *" -> "char*" */
static void normalizeType(const char* in, char* out, size_t cap)
{
    size_t n = 0;
    while (*in && n + 1 < cap) {
        if (*in == ' ' || *in == '\t' || *in == '&') { ++in; continue; }
        if (strncmp(in, "const", 5) == 0 && (in[5] == 0 || in[5] == ' ' || in[5] == '&' || in[5] == '*')) { in += 5; continue; }
        if (strncmp(in, "volatile", 8) == 0 && (in[8] == 0 || in[8] == ' ' || in[8] == '&' || in[8] == '*')) { in += 8; continue; }
        out[n++] = *in++;
    }
    out[n] = 0;
}

static const char* lastComponent(const char* s)
{
    const char* p = strstr(s, "::");
    while (p) { s = p + 2; p = strstr(s, "::"); }
    return s;
}

static int sameType(const char* thrown, const char* caught)
{
    char a[256], b[256];
    normalizeType(thrown, a, sizeof a);
    normalizeType(caught, b, sizeof b);
    if (strcmp(a, b) == 0) return 1;
    return strcmp(lastComponent(a), lastComponent(b)) == 0;   /* "geom::Error" matches "Error" */
}

/* "const volatile X*", with the pointer's own qualifiers after the '*' ignored: X and the pointee's qualifiers (1 const,
   2 volatile). 0 for anything but a pointer to a type that is not itself a pointer */
static int splitPointer(const char* t, char* out, size_t cap, int* cv)
{
    size_t n = strlen(t), k = 0;
    *cv = 0;
    for (;;) {
        while (n > 0 && t[n - 1] == ' ') --n;
        if (n >= 6 && strncmp(t + n - 6, " const", 6) == 0) n -= 6;
        else if (n >= 9 && strncmp(t + n - 9, " volatile", 9) == 0) n -= 9;
        else break;
    }
    if (n == 0 || t[n - 1] != '*') return 0;
    --n;
    for (;;) {
        while (n > 0 && *t == ' ') { ++t; --n; }
        if (n > 6 && strncmp(t, "const ", 6) == 0) { *cv |= 1; t += 6; n -= 6; }
        else if (n > 9 && strncmp(t, "volatile ", 9) == 0) { *cv |= 2; t += 9; n -= 9; }
        else break;
    }
    while (n > 0 && t[n - 1] == ' ') --n;
    if (n == 0 || n >= cap) return 0;
    {
        int depth = 0;   /* a '*' inside template arguments belongs to them */
        for (k = 0; k < n; ++k) {
            if (t[k] == '<') ++depth;
            else if (t[k] == '>') --depth;
            else if (depth == 0 && (t[k] == '*' || t[k] == '&' || t[k] == '(')) return 0;
        }
    }
    for (k = 0; k < n; ++k) out[k] = t[k];
    out[n] = 0;
    return 1;
}

/* the last successful match: the offset of the base subobject it found ("Base@16" in the descriptor), which
   cppparse_catch_begin adds to the object address it returns, or the offset to add to a thrown pointer that is not
   null ("Base*+16"); a virtual base of the pointee ("Base*+v8:4+16": the vbptr at 8, its vbtable's entry at 4, then
   16 further) lies where the pointed-to object's vbtable says, as the object may be of a class derived from the
   pointee's */
static __declspec(thread) unsigned long g_matchOffset = 0;
static __declspec(thread) int           g_matchPointer = 0;
static __declspec(thread) int           g_matchVirtual = 0;
static __declspec(thread) unsigned long g_matchVbptr = 0;
static __declspec(thread) unsigned long g_matchVbentry = 0;

static void parseOffset(const char* s)
{
    if (*s == 'v') {
        g_matchVirtual = 1;
        g_matchVbptr = strtoul(s + 1, (char**)&s, 10);
        g_matchVbentry = *s == ':' ? strtoul(s + 1, (char**)&s, 10) : 0;
        g_matchOffset = *s == '+' ? strtoul(s + 1, 0, 10) : 0;
    } else g_matchOffset = strtoul(s, 0, 10);
}

static char* adjustPointer(char* v)
{
    if (!v) return 0;
    if (g_matchVirtual) {
        char* vbptr = v + g_matchVbptr;
        v = vbptr + *(const int*)(*(const char**)vbptr + g_matchVbentry);
    }
    return v + g_matchOffset;
}

int cppparse_match(const char* catchType)
{
    const char* p;
    char want[256];
    int wantCv = 0, wantPointer;
    if (!g_inflight.type) return 0;
    g_matchOffset = 0;
    g_matchPointer = 0;
    g_matchVirtual = 0;
    if (strcmp(catchType, "...") == 0) return 1;
    wantPointer = splitPointer(catchType, want, sizeof want, &wantCv);
    p = g_inflight.type;
    while (*p) {
        const char* e = strchr(p, ';');
        size_t n = e ? (size_t)(e - p) : strlen(p);
        char entry[256];
        if (n >= sizeof entry) n = sizeof entry - 1;
        memcpy(entry, p, n);
        entry[n] = 0;
        {
            char* at = strchr(entry, '@');
            char* plus = strchr(entry, '+');
            char have[256];
            int haveCv = 0;
            if (at) *at = 0;
            if (plus) *plus = 0;
            if (wantPointer && splitPointer(entry, have, sizeof have, &haveCv)) {
                /* a pointer handler: a qualification conversion may add cv-qualifiers to the pointee, not drop them */
                if ((haveCv & ~wantCv) == 0 && sameType(have, want)) { if (plus) parseOffset(plus + 1); g_matchPointer = 1; return 1; }
            } else if (sameType(entry, catchType)) { if (at) parseOffset(at + 1); return 1; }
        }
        p = e ? e + 1 : p + n;
    }
    return 0;
}

void* cppparse_catch_begin(void)
{
    void* obj = g_inflight.object;
    pushCaught(&g_inflight);
    if (obj && g_matchPointer && g_inflight.slot) {
        /* the thrown pointer converted to the handler's: the thrown one stays as it was for a "throw;" */
        *g_inflight.slot = adjustPointer(*(char**)obj);
        obj = g_inflight.slot;
    } else if (obj) obj = (char*)obj + g_matchOffset;
    g_matchOffset = 0;
    g_matchPointer = 0;
    g_matchVirtual = 0;
    g_inflight.object = 0;
    g_inflight.type = 0;
    g_inflight.size = 0;
    g_inflight.dtor = 0;
    g_inflight.slot = 0;
    return obj;
}

void cppparse_catch_end(void)
{
    if (g_caughtCount > 0) {
        --g_caughtCount;
        dropException(&g_caught[g_caughtCount]);
    }
}

/* the handler got the address of the object, of one of its base subobjects, or of the converted pointer */
static int holds(const struct cppparse_exception* e, const void* p)
{
    if (e->slot && p == (const void*)e->slot) return 1;
    return (const char*)p >= (const char*)e->object && (const char*)p < (const char*)e->object + (e->size ? e->size : 1);
}

/* an exception is leaving a handler (the landing pad around a handler body calls this, having just caught it): the
   exception that handler handled ends, unless it is the one leaving ("throw;" in the handler) */
void cppparse_catch_unwind(void* handled)
{
    int k;
    if (g_caughtCount == 0 || holds(&g_caught[g_caughtCount - 1], handled)) return;
    for (k = g_caughtCount - 2; k >= 0; --k)
        if (holds(&g_caught[k], handled)) {
            dropException(&g_caught[k]);
            for (; k + 1 < g_caughtCount; ++k) g_caught[k] = g_caught[k + 1];
            --g_caughtCount;
            return;
        }
}

/* an exception left a destructor that the stack unwinding called (the landing pad's own region): C++98 15.5.1 calls
   terminate, whose default handler is abort, as cl's code does */
void (*cppparse_set_terminate(void (*f)(void)))(void) { void (*old)(void) = g_terminateHandler; g_terminateHandler = f; return old; }
void (*cppparse_set_unexpected(void (*f)(void)))(void) { void (*old)(void) = g_unexpectedHandler; g_unexpectedHandler = f; return old; }
/* the landing pads count the destructors they run while an exception is unwinding (cppparse_catch_begin has
   taken the exception by then): std::uncaught_exception() is true there and from the throw to the handler */
static __declspec(thread) int g_unwinding = 0;
void cppparse_unwind_enter(void) { ++g_unwinding; }
void cppparse_unwind_leave(void) { --g_unwinding; }
int cppparse_uncaught_exception(void) { return g_inflight.object != 0 || g_unwinding > 0; }
void cppparse_unexpected(void)
{
    if (g_unexpectedHandler) g_unexpectedHandler();
    if (g_terminateHandler) g_terminateHandler();
    abort();
}

void cppparse_terminate(void)
{
    if (g_terminateHandler) { g_terminateHandler(); abort(); }
    fprintf(stderr, "cppparse runtime: terminate: an exception left a destructor during stack unwinding\n");
    abort();
}

void cppparse_rethrow(void)
{
    if (!g_inflight.type) {                       /* "throw;" inside a handler */
        if (g_caughtCount == 0) { fprintf(stderr, "cppparse runtime: throw; with no active exception\n"); abort(); }
        g_inflight = g_caught[--g_caughtCount];
    }
    dispatch();
}

/* atomic counters for code compiled by cppparse (MSVC's InterlockedIncrement is a compiler intrinsic); the library
   headers use them too (include\__locale: the locales' reference counts, the facet ids), whichever compiler builds them */
long cppparse_interlocked_increment(long volatile* value) { return _InterlockedIncrement(value); }
long cppparse_interlocked_decrement(long volatile* value) { return _InterlockedDecrement(value); }
long cppparse_interlocked_compare_exchange(long volatile* value, long exchange, long comparand) { return _InterlockedCompareExchange(value, exchange, comparand); }

/* no longer used by generated code, which guards static locals with cl's protocol (an int $TSS guard and the
   CRT's _Init_thread_header/_Init_thread_footer), kept for objects built by older versions.
   static locals that need construction: the generated code tests the guard byte and, when it is clear, calls
   cppparse_static_enter, which returns 1 with the lock held when this thread is to run the initializer (it
   then calls cppparse_static_leave) and 0 when another thread finished it meanwhile. One lock serves every
   static local and is recursive, since an initializer may reach another static local. An initializer that
   throws leaves the lock held by its thread (the generated code has no handler around it) */
static long volatile g_staticOwner = 0;   /* thread id of the holder, 0 when free */
static int           g_staticDepth = 0;

static void staticAcquire(void)
{
    long self = (long)GetCurrentThreadId();
    if (g_staticOwner == self) { ++g_staticDepth; return; }
    while (_InterlockedCompareExchange(&g_staticOwner, self, 0) != 0) SwitchToThread();
    g_staticDepth = 1;
}

static void staticRelease(void)
{
    if (--g_staticDepth == 0) _InterlockedExchange(&g_staticOwner, 0);
}

int cppparse_static_enter(unsigned char volatile* guard)
{
    staticAcquire();
    if (*guard) { staticRelease(); return 0; }
    return 1;
}

void cppparse_static_leave(unsigned char volatile* guard)
{
    *guard = 1;
    staticRelease();
}

/* for tests: both must be 0 when no try region is active and no handler is running */
int cppparse_frame_depth(void)
{
    int n = 0;
    struct cppparse_frame* f;
    for (f = g_top; f; f = f->prev) ++n;
    return n;
}

int cppparse_caught_depth(void) { return g_caughtCount; }

/* for tests of the unwind tables: walks the stack from the caller with RtlVirtualUnwind, as an exception does,
   counting the frames of the function that starts at 'counted', up to the first frame of the function that starts
   at 'stop'; there it stores the callee-saved registers as the unwind restored them (rbx rbp rsi rdi r12 r13 r14
   r15, then the low halves of xmm6..xmm15) and returns the count. -1 when 'stop' is not reached */
static const char* functionStart(const void* p)
{
    /* an incrementally linked image gives the address of a jump thunk: follow its jmp rel32 */
    const unsigned char* c = (const unsigned char*)p;
    if (c[0] == 0xE9) { int rel; memcpy(&rel, c + 1, sizeof rel); return (const char*)(c + 5 + rel); }
    return (const char*)p;
}

int cppparse_walk_frames(const void* stop, const void* counted, unsigned long long* ints, unsigned long long* xmms)
{
    CONTEXT ctx;
    int frames = 0, i;
    stop = functionStart(stop);
    counted = functionStart(counted);
    RtlCaptureContext(&ctx);
    for (i = 0; i < 1024 && ctx.Rip; ++i) {
        DWORD64 base = 0;
        PRUNTIME_FUNCTION rf = RtlLookupFunctionEntry(ctx.Rip, &base, 0);
        const char* begin = rf ? (const char*)base + rf->BeginAddress : 0;
        if (begin && begin == (const char*)stop) {
            const M128A* x = &ctx.Xmm6;
            int k;
            ints[0] = ctx.Rbx; ints[1] = ctx.Rbp; ints[2] = ctx.Rsi; ints[3] = ctx.Rdi;
            ints[4] = ctx.R12; ints[5] = ctx.R13; ints[6] = ctx.R14; ints[7] = ctx.R15;
            for (k = 0; k < 10; ++k) xmms[k] = x[k].Low;
            return frames;
        }
        if (begin && begin == (const char*)counted) ++frames;
        if (!rf) { ctx.Rip = *(DWORD64*)ctx.Rsp; ctx.Rsp += 8; }      /* a leaf without a table entry */
        else {
            void* handlerData = 0;
            DWORD64 establisher = 0;
            RtlVirtualUnwind(UNW_FLAG_NHANDLER, base, ctx.Rip, rf, &ctx, &handlerData, &establisher, 0);
        }
    }
    return -1;
}

}
